create table xxventuri.eba_sales_territory_acl (
    id                 number,
    row_version_number number,
    row_key            varchar2(255 byte),
    territory_id       number,
    userid             varchar2(255 byte) not null enable,
    acl_comments       varchar2(4000 byte),
    created_by         varchar2(255 byte),
    created            timestamp(6) with local time zone,
    updated_by         varchar2(255 byte),
    updated            timestamp(6) with local time zone,
    flex_01            varchar2(255 byte),
    flex_02            varchar2(255 byte),
    flex_03            varchar2(255 byte),
    flex_04            varchar2(255 byte),
    flex_05            varchar2(255 byte),
    flex_06            varchar2(255 byte),
    flex_07            varchar2(255 byte),
    flex_08            varchar2(255 byte),
    flex_09            varchar2(255 byte),
    flex_10            varchar2(255 byte)
);

alter table xxventuri.eba_sales_territory_acl add primary key ( id )
    using index enable;


